SELECT DATE(generated_at) AS d, interval_code, signal_mode, COUNT(*) AS n, SUM(decision IN ('BUY','STRONG_BUY')) AS buys, SUM(final_entry_allowed = 1 AND decision IN ('BUY','STRONG_BUY')) AS allowed_buys, MAX(generated_at) AS last_gen FROM crypto_ai.trade_signal WHERE generated_at >= '2026-10-14 00:00:00' GROUP BY DATE(generated_at), interval_code, signal_mode ORDER BY d, interval_code LIMIT 100;